#include "FileHandler.h"
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <cstdio>

namespace library {
namespace {
std::string encode(const std::string& s){std::string out;for(unsigned char c:s){if(c=='%'||c=='|'||c=='\n'||c=='\r'){char b[4];std::snprintf(b,sizeof(b),"%%%02X",static_cast<unsigned int>(c));out+=b;}else out+=static_cast<char>(c);}return out;}
std::string decode(const std::string& s){std::string out;for(size_t i=0;i<s.size();++i){if(s[i]=='%'&&i+2<s.size()){unsigned int v=0;std::istringstream in(s.substr(i+1,2));in>>std::hex>>v;if(in){out+=static_cast<char>(v);i+=2;continue;}}out+=s[i];}return out;}
std::vector<std::string> split(const std::string& s){std::vector<std::string> a;size_t start=0;while(true){size_t end=s.find('|',start);if(end==std::string::npos){a.push_back(decode(s.substr(start)));break;}a.push_back(decode(s.substr(start,end-start)));start=end+1;}return a;}
}
void FileHandler::save(const std::filesystem::path& path,const LibraryDatabase& db){std::ofstream f(path,std::ios::binary|std::ios::trunc);if(!f)throw std::runtime_error("Could not open data file for writing.");f<<"SMARTLIBRARY|1\n";for(auto&i:db.items())f<<"ITEM|"<<encode(i->id())<<'|'<<toString(i->type())<<'|'<<encode(i->title())<<'|'<<encode(i->author())<<'|'<<i->year()<<'|'<<encode(i->borrowerId())<<'|'<<encode(i->dueDate())<<'|'<<i->borrowCount()<<'|'<<db.accessCount(i->id())<<'\n';for(auto&[id,u]:db.users()){f<<"USER|"<<encode(id)<<'|'<<encode(u.displayName)<<'\n';for(auto&r:u.history)f<<"HISTORY|"<<encode(id)<<'|'<<encode(r.itemId)<<'|'<<encode(r.title)<<'|'<<encode(r.borrowedOn)<<'|'<<encode(r.returnedOn)<<'\n';}for(auto&r:db.reservations())f<<"RESERVATION|"<<encode(r.itemId)<<'|'<<encode(r.userId)<<'|'<<encode(r.placedAt)<<'\n';if(!f)throw std::runtime_error("An error occurred while saving library data.");}
LibraryDatabase FileHandler::load(const std::filesystem::path& path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("Could not open the selected data file.");LibraryDatabase db;std::string line;bool header=false;while(std::getline(f,line)){auto a=split(line);if(a.empty())continue;if(!header){if(a.size()<2||a[0]!="SMARTLIBRARY"||a[1]!="1")throw std::runtime_error("This is not a supported library data file.");header=true;continue;}try{if(a[0]=="ITEM"&&a.size()>=10){auto type=itemTypeFromString(a[2]);std::shared_ptr<LibraryItem> i;if(type==ItemType::Book)i=std::make_shared<Book>(a[1],a[3],a[4],std::stoi(a[5]));else if(type==ItemType::Magazine)i=std::make_shared<Magazine>(a[1],a[3],a[4],std::stoi(a[5]));else i=std::make_shared<Journal>(a[1],a[3],a[4],std::stoi(a[5]));if(!a[6].empty())i->checkOut(a[6],a[7]);i->setBorrowCount(std::stol(a[8]));db.addItem(i);db.restoreAccessCount(a[1],std::stol(a[9]));}else if(a[0]=="USER"&&a.size()>=3){db.users()[a[1]]={a[1],a[2],{}};}else if(a[0]=="HISTORY"&&a.size()>=6){auto&u=db.getOrCreateUser(a[1]);u.history.push_back({a[2],a[3],a[4],a[5]});}else if(a[0]=="RESERVATION"&&a.size()>=4){db.reservations().push_back({a[1],a[2],a[3]});}}catch(const std::exception& ex){throw std::runtime_error(std::string("Invalid data file: ")+ex.what());}}if(!header)throw std::runtime_error("The selected data file is empty.");return db;}
}
